bool ServoStyleSet::StyleDocument(ServoTraversalFlags aFlags) {
  AUTO_PROFILER_LABEL_CATEGORY_PAIR_RELEVANT_FOR_JS(LAYOUT_StyleComputation);
  MOZ_ASSERT(GetPresContext(), "Styling a document without a shell?");

  if (!mDocument->GetServoRestyleRoot()) {
    return false;
  }

  PreTraverse(aFlags);
  const SnapshotTable& snapshots = Snapshots();

  // Restyle the document from the root element and each of the document level
  // NAC subtree roots.
  bool postTraversalRequired = false;

  if (ShouldTraverseInParallel()) {
    aFlags |= ServoTraversalFlags::ParallelTraversal;
  }

  // Do the first traversal.
  DocumentStyleRootIterator iter(mDocument->GetServoRestyleRoot());
  while (Element* root = iter.GetNextStyleRoot()) {
    MOZ_ASSERT(MayTraverseFrom(root));

    Element* parent = root->GetFlattenedTreeParentElementForStyle();
    MOZ_ASSERT_IF(parent,
                  !parent->HasAnyOfFlags(Element::kAllServoDescendantBits));

    if (MOZ_UNLIKELY(!root->HasServoData()) && !parent) {
      StyleNewSubtree(root);
      postTraversalRequired = true;
      continue;
    }

    AutoPrepareTraversal guard(this);

    postTraversalRequired |=
        Servo_TraverseSubtree(root, mRawData.get(), &snapshots, aFlags) ||
        root->HasAnyOfFlags(Element::kAllServoDescendantBits |
                            NODE_NEEDS_FRAME);

void ServoStyleSet::StyleNewSubtree(Element* aRoot) {
  MOZ_ASSERT(GetPresContext());
  MOZ_ASSERT(!aRoot->HasServoData());
  MOZ_ASSERT(aRoot->GetFlattenedTreeParentNodeForStyle(),
             "Not in the flat tree? Fishy!");
  PreTraverseSync();
  AutoPrepareTraversal guard(this);

  // Do the traversal. The snapshots will not be used.
  const SnapshotTable& snapshots = Snapshots();
  auto flags = ServoTraversalFlags::Empty;
  if (ShouldTraverseInParallel()) {
    flags |= ServoTraversalFlags::ParallelTraversal;
  }

  DebugOnly<bool> postTraversalRequired =
      Servo_TraverseSubtree(aRoot, mRawData.get(), &snapshots, flags);
  MOZ_ASSERT(!postTraversalRequired);

  // Annoyingly, the newly-styled content may have animations that need
  // starting, which requires traversing them again. Mark the elements
  // that need animation processing, then do a forgetful traversal to
  // update the styles and clear the animation bits.
  if (GetPresContext()->EffectCompositor()->PreTraverseInSubtree(flags,
                                                                 aRoot)) {
    postTraversalRequired =
        Servo_TraverseSubtree(aRoot, mRawData.get(), &snapshots,
                              ServoTraversalFlags::AnimationOnly |
                                  ServoTraversalFlags::FinalAnimationTraversal);
    MOZ_ASSERT(!postTraversalRequired);
  }
}

nsIFrame* nsCSSFrameConstructor::ConstructDocElementFrame(
    Element* aDocElement) {
  MOZ_ASSERT(GetRootFrame(),
             "No viewport?  Someone forgot to call ConstructRootFrame!");
  MOZ_ASSERT(!mDocElementContainingBlock,
             "Shouldn't have a doc element containing block here");

  // Ensure the document element is styled at this point.
  // FIXME(emilio, bug 1852735): This is only needed because of the sync frame
  // construction from PresShell::Initialize.
  if (!aDocElement->HasServoData()) {
    mPresShell->StyleSet()->StyleNewSubtree(aDocElement);
  }
  aDocElement->UnsetFlags(NODE_DESCENDANTS_NEED_FRAMES | NODE_NEEDS_FRAME);

void nsCSSFrameConstructor::StyleNewChildRange(nsIContent* aStartChild,
                                               nsIContent* aEndChild) {
  ServoStyleSet* styleSet = mPresShell->StyleSet();

  for (nsIContent* child = aStartChild; child != aEndChild;
       child = child->GetNextSibling()) {
    if (!child->IsElement()) {
      continue;
    }

    Element* childElement = child->AsElement();

    // We only come in here from non-lazy frame construction, so the children
    // should be unstyled.
    MOZ_ASSERT(!childElement->HasServoData());

#ifdef DEBUG
    {
      // Furthermore, all of them should have the same flattened tree parent
      // (GetRangeInsertionPoint ensures it). And that parent should be styled,
      // otherwise we would've never found an insertion point at all.
      Element* parent = childElement->GetFlattenedTreeParentElement();
      MOZ_ASSERT(parent);
      MOZ_ASSERT(parent->HasServoData());
      MOZ_ASSERT(
          IsFlattenedTreeChild(parent, child),
          "GetFlattenedTreeParent and ChildIterator don't agree, fix this!");
    }
#endif

    styleSet->StyleNewSubtree(childElement);
  }

#[cfg(feature = "gecko")]
fn process_animations(
    &self,
    context: &mut StyleContext<Self>,
    old_styles: &mut ElementStyles,
    new_styles: &mut ResolvedElementStyles,
    important_rules_changed: bool,
) {
    use crate::context::UpdateAnimationsTasks;

    let old_values = &old_styles.primary;
    if context.shared.traversal_flags.for_animation_only() && old_values.is_some() {
        return;
    }

// Update root font-relative units. If any of these unit values changed
// since last time, ensure that we recascade the entire tree.
if is_root {
    debug_assert!(self.owner_doc_matches_for_testing(device));
    device.set_root_style(new_primary_style);

    // Update root font size for rem units
    if font_size_changed {
        let size = new_font_size.computed_size();
        device.set_root_font_size(new_primary_style.effective_zoom.unzoom(size.px()));
    }

    // Update root line height for rlh units
    if line_height_likely_changed {
        let new_line_height = device
            .calc_line_height(
                new_primary_style.get_font(),
                new_primary_style.writing_mode,
                None,
            )
            .0;
        device.set_root_line_height(
            new_primary_style
                .effective_zoom
                .unzoom(new_line_height.px()),
        );
    }

    // Update root font metrics for rcap, rch, rex, ric units. Since querying
    // font metrics can be an expensive call, they are only updated if these
    // units are used in the document.
    if device.used_root_font_metrics() && device.update_root_font_metrics() {
        child_restyle_hint |= RestyleHint::RESTYLE_IF_AFFECTED_BY_WM_OR_ANCESTOR_FONT;
    }
}

if font_size_changed || line_height_likely_changed {
    child_restyle_hint |= RestyleHint::RESTYLE_IF_AFFECTED_BY_WM_OR_ANCESTOR_FONT;
}

// Don't accumulate damage if we're in the final animation traversal.
if context
    .shared
    .traversal_flags
    .contains(TraversalFlags::FinalAnimationTraversal)
{
    return RestyleHint::RECASCADE_SELF;
}

// Also, don't do anything if there was no style.
let old_primary_style = match old_styles.primary {
    Some(s) => s,
    None => return RestyleHint::RECASCADE_SELF,
};

where
    E: TElement,
{
    if flags.intersects(TraversalFlags::FinalAnimationTraversal) {
        debug_assert!(flags.for_animation_only());
        data.clear_restyle_flags_and_damage();
        unsafe {
            element.unset_animation_only_dirty_descendants();
        }
    }
}

let needs_animation_only_restyle =
    element.has_animation_only_dirty_descendants() || element.has_animation_restyle_hints();

let per_doc_data = raw_data.borrow();
debug_assert!(!per_doc_data.stylist.stylesheets_have_changed());

let global_style_data = &*GLOBAL_STYLE_DATA;
let guard = global_style_data.shared_lock.read();

let was_initial_style = !element.has_data();

if needs_animation_only_restyle {
    debug!(
        "Servo_TraverseSubtree doing animation-only restyle (aodd={})",
        element.has_animation_only_dirty_descendants()
    );
    traverse_subtree(
        element,
        &global_style_data,
        &per_doc_data,
        &guard,
        traversal_flags | TraversalFlags::AnimationOnly,
        unsafe { &*snapshots },
    );
}

traverse_subtree(
    element,
    &global_style_data,
    &per_doc_data,
    &guard,
    traversal_flags,
    unsafe { &*snapshots },
);
